import { useState, useCallback } from 'react'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Slider } from '@/components/ui/slider'
import { Badge } from '@/components/ui/badge'
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import {
  predictColdStart,
  generateScreeningDOE,
  generateRSMDOE,
  DEFAULT_FACTORS,
  type Formulation,
  type PredictionResult,
  type DOERun,
} from '@/lib/physics'

// ──────────────────────────────────────────────
// 타입 정의
// ──────────────────────────────────────────────
interface ExperimentRecord {
  id: number
  lot: string
  formulation: Formulation
  prediction: PredictionResult
  actual?: {
    hdt?: number
    izod?: number
    mfi?: number
    voc?: number
  }
  date: string
  note: string
}

// ──────────────────────────────────────────────
// 상수
// ──────────────────────────────────────────────
const SPEC = {
  hdt: { target: 115, unit: '℃', label: 'HDT (1.8MPa)' },
  izod: { target: 15, unit: 'kJ/m²', label: 'Izod 충격' },
  voc: { target: 50, unit: 'µg/g', label: 'TVOC (VDA278)' },
}

const DEFAULT_FORM: Formulation = {
  npmi: 17,
  gAbs: 28,
  san: 50,
  anContent: 28,
  cbMB: 2.5,
  antioxidant: 0.5,
  lubricant: 1.0,
  injTemp: 250,
  moldTemp: 70,
}

// ──────────────────────────────────────────────
// 유틸 컴포넌트
// ──────────────────────────────────────────────
function SpecLight({ pass }: { pass: boolean | null }) {
  if (pass === true) return <span className="inline-block w-3 h-3 rounded-full bg-green-500" title="통과" />
  if (pass === false) return <span className="inline-block w-3 h-3 rounded-full bg-red-500" title="미달" />
  return <span className="inline-block w-3 h-3 rounded-full bg-yellow-400" title="주의" />
}

function PredBar({ value, low, high, unit, spec, higherIsBad = false }: {
  value: number; low: number; high: number; unit: string; spec?: number; higherIsBad?: boolean
}) {
  const pass = spec == null ? null : higherIsBad ? value <= spec : value >= spec
  const color = pass === true ? 'text-green-600' : pass === false ? 'text-red-600' : 'text-yellow-600'
  return (
    <div className="flex items-center gap-3">
      <span className={`font-mono text-lg font-bold w-24 text-right ${color}`}>
        {value.toFixed(1)}<span className="text-xs font-normal ml-1">{unit}</span>
      </span>
      <span className="text-xs text-gray-400 font-mono">
        [{low.toFixed(1)} – {high.toFixed(1)}]
      </span>
      {spec != null && <SpecLight pass={pass} />}
    </div>
  )
}

function SliderRow({ label, value, min, max, step = 0.5, unit, onChange, warn }: {
  label: string; value: number; min: number; max: number; step?: number; unit: string;
  onChange: (v: number) => void; warn?: string
}) {
  return (
    <div className="grid grid-cols-[160px_1fr_64px] items-center gap-3 py-1">
      <Label className="text-sm">{label}</Label>
      <Slider
        min={min} max={max} step={step} value={[value]}
        onValueChange={([v]) => onChange(v)}
        className="w-full"
      />
      <span className="text-sm font-mono text-right">
        {value}<span className="text-gray-400 text-xs ml-0.5">{unit}</span>
      </span>
      {warn && <span className="col-span-3 text-xs text-yellow-600 -mt-1">{warn}</span>}
    </div>
  )
}

// ──────────────────────────────────────────────
// M1 + M2: 배합 입력기 & 물성 예측기
// ──────────────────────────────────────────────
function PredictorTab({ records, onAddRecord }: {
  records: ExperimentRecord[]
  onAddRecord: (r: ExperimentRecord) => void
}) {
  const [form, setForm] = useState<Formulation>(DEFAULT_FORM)
  const [pred, setPred] = useState<PredictionResult | null>(null)
  const [lotName, setLotName] = useState('')

  const totalComposition = form.npmi + form.gAbs + form.cbMB
  const sanEst = Math.max(0, 100 - totalComposition)
  const compositonOk = totalComposition <= 100

  const set = useCallback((key: keyof Formulation) => (v: number) => {
    setForm(f => ({ ...f, [key]: v }))
    setPred(null)
  }, [])

  const handlePredict = () => {
    const result = predictColdStart({ ...form, san: sanEst })
    setPred(result)
  }

  const handleSave = () => {
    if (!pred) return
    const rec: ExperimentRecord = {
      id: Date.now(),
      lot: lotName || `LOT-${records.length + 1}`,
      formulation: { ...form, san: sanEst },
      prediction: pred,
      date: new Date().toLocaleDateString('ko-KR'),
      note: '',
    }
    onAddRecord(rec)
    setLotName('')
  }

  return (
    <div className="grid grid-cols-[1fr_340px] gap-4">
      {/* 왼쪽: 입력 패널 */}
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-base">M1 — 배합 입력기</CardTitle>
          <p className="text-xs text-gray-500">조성 합계: <strong className={compositonOk ? 'text-green-600' : 'text-red-600'}>{totalComposition.toFixed(1)} wt%</strong> (CB·AO·활제 별도) / SAN 추정: <strong>{sanEst.toFixed(1)} wt%</strong></p>
        </CardHeader>
        <CardContent className="space-y-1">
          <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide pt-1">── 주요 조성</p>
          <SliderRow label="N-PMI 함량" value={form.npmi} min={10} max={25} step={0.5} unit="wt%" onChange={set('npmi')} />
          <SliderRow label="g-ABS(고무)" value={form.gAbs} min={20} max={40} step={0.5} unit="wt%" onChange={set('gAbs')} />
          <SliderRow label="SAN AN 함량" value={form.anContent} min={24} max={32} step={0.5} unit="%" onChange={set('anContent')} />
          <SliderRow label="카본블랙 MB" value={form.cbMB} min={2} max={3} step={0.1} unit="wt%" onChange={set('cbMB')} />

          <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide pt-3">── 첨가제</p>
          <SliderRow label="산화방지제" value={form.antioxidant} min={0.3} max={0.8} step={0.05} unit="phr" onChange={set('antioxidant')} />
          <SliderRow label="활제 (EBS)" value={form.lubricant} min={0.5} max={1.5} step={0.1} unit="phr" onChange={set('lubricant')} />

          <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide pt-3">── 공정 조건</p>
          <SliderRow label="사출 온도" value={form.injTemp} min={240} max={260} step={1} unit="℃" onChange={set('injTemp')}
            warn={form.injTemp > 255 ? '⚠ 고온 체류 시 VOC 증가 위험' : undefined} />
          <SliderRow label="금형 온도" value={form.moldTemp} min={60} max={80} step={1} unit="℃" onChange={set('moldTemp')} />

          {!compositonOk && (
            <p className="text-xs text-red-600 pt-1">⚠ 조성 합계가 100%를 초과합니다. N-PMI 또는 g-ABS를 줄이세요.</p>
          )}

          <div className="flex gap-2 pt-3">
            <Button onClick={handlePredict} disabled={!compositonOk} className="flex-1">
              물성 예측 실행
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* 오른쪽: 예측 결과 */}
      <div className="space-y-3">
        <Card>
          <CardHeader className="pb-2">
            <div className="flex items-center justify-between">
              <CardTitle className="text-base">M2 — 물성 예측 결과</CardTitle>
              {pred && (
                <Badge variant="outline" className="text-xs">
                  Cold-start (데이터 0건)
                </Badge>
              )}
            </div>
          </CardHeader>
          <CardContent>
            {!pred ? (
              <p className="text-sm text-gray-400 text-center py-6">배합 입력 후 [물성 예측 실행] 클릭</p>
            ) : (
              <div className="space-y-3">
                <div className="grid grid-cols-[120px_1fr] gap-y-2 text-sm">
                  <span className="text-gray-500">{SPEC.hdt.label}</span>
                  <PredBar {...pred.hdt} unit="℃" spec={SPEC.hdt.target} />
                  <span className="text-gray-500">Vicat</span>
                  <PredBar {...pred.vicat} unit="℃" />
                  <span className="text-gray-500">{SPEC.izod.label}</span>
                  <PredBar {...pred.izod} unit="kJ/m²" spec={SPEC.izod.target} />
                  <span className="text-gray-500">MFI (220℃/10kg)</span>
                  <PredBar {...pred.mfi} unit="g/10min" />
                  <span className="text-gray-500">{SPEC.voc.label}</span>
                  <PredBar {...pred.voc} unit="µg/g" spec={SPEC.voc.target} higherIsBad />
                  <span className="text-gray-500">원가 지수</span>
                  <PredBar {...pred.cost} unit="₩/kg" />
                </div>

                {/* Spec 게이트 신호등 */}
                <div className="border-t pt-2 mt-2">
                  <p className="text-xs font-semibold text-gray-400 mb-2">M8 — Spec 게이트 판정</p>
                  <div className="flex gap-3">
                    {Object.entries(pred.specPass).map(([key, val]) => (
                      <div key={key} className="flex items-center gap-1.5 text-xs">
                        <SpecLight pass={val} />
                        <span>{key.toUpperCase()} {SPEC[key as keyof typeof SPEC]?.target}{SPEC[key as keyof typeof SPEC]?.unit}</span>
                      </div>
                    ))}
                  </div>
                  <p className="text-xs text-gray-400 mt-2">
                    오차범위는 cold-start 기준 (±7~30%). 실측 데이터 누적 시 신뢰구간 축소.
                  </p>
                </div>

                {/* 저장 */}
                <div className="border-t pt-2 flex gap-2">
                  <Input
                    placeholder="LOT 번호 (선택)"
                    value={lotName}
                    onChange={e => setLotName(e.target.value)}
                    className="text-sm h-8"
                  />
                  <Button size="sm" variant="outline" onClick={handleSave}>
                    트래커 저장
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Trade-off 요약 */}
        {pred && (
          <Card>
            <CardHeader className="pb-1">
              <CardTitle className="text-sm">Trade-off 인사이트</CardTitle>
            </CardHeader>
            <CardContent className="text-xs space-y-1 text-gray-600">
              {form.npmi > 20 && <p>🔺 N-PMI {form.npmi}% — 내열↑ 좋지만 충격↓·MFI↓ 주의</p>}
              {form.npmi < 13 && <p>🔻 N-PMI {form.npmi}% — 충격·유동↑ 좋지만 HDT 115℃ 달성 어려울 수 있음</p>}
              {form.gAbs > 35 && <p>🔺 고무 {form.gAbs}% — 충격↑이지만 HDT·강성↓, VOC도 증가 경향</p>}
              {form.injTemp > 255 && <p>⚠ 사출온도 {form.injTemp}℃ — 체류 길어지면 TVOC spike 위험 (VDA278 미달 리스크)</p>}
              {pred.specPass.hdt === false && <p>❌ HDT 미달 예측 → N-PMI 2~3% 추가 검토 또는 DOE 실험 설계 권장</p>}
              {pred.specPass.voc === false && <p>❌ VOC 초과 예측 → 탈휘발 조건 강화 또는 산화방지제 패키지 재검토</p>}
              {pred.specPass.hdt === true && pred.specPass.izod === true && pred.specPass.voc === true && (
                <p>✅ 현 배합이 3대 Spec 통과 예측. 실배합으로 검증 권장.</p>
              )}
              {pred.specPass.hdt === null && <p>⚠ HDT 경계구간 (110~115℃) — 실험 우선 실시 권장</p>}
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  )
}

// ──────────────────────────────────────────────
// M3: DOE 설계기
// ──────────────────────────────────────────────
function DOETab() {
  const [mode, setMode] = useState<'screening' | 'rsm'>('screening')
  const [factors, setFactors] = useState(DEFAULT_FACTORS)
  const [runs, setRuns] = useState<DOERun[]>([])

  const handleGenerate = () => {
    const result = mode === 'screening'
      ? generateScreeningDOE(factors)
      : generateRSMDOE(factors)
    setRuns(result)
  }

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-base">M3 — DOE 설계기</CardTitle>
          <p className="text-xs text-gray-500">
            스크리닝: PB12 (12회, 7인자 주효과 분리) → RSM: Box-Behnken (15회, 지배 3인자 곡률·상호작용)
          </p>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex gap-3 items-center">
            <Select value={mode} onValueChange={v => { setMode(v as typeof mode); setRuns([]) }}>
              <SelectTrigger className="w-56">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="screening">스크리닝 DOE — Plackett-Burman 12</SelectItem>
                <SelectItem value="rsm">반응표면 DOE — Box-Behnken 15</SelectItem>
              </SelectContent>
            </Select>
            <Button onClick={handleGenerate}>실험 세트 생성</Button>
            <span className="text-xs text-gray-400">
              {mode === 'screening' ? '예상 실험 수: 12회' : '예상 실험 수: 15회'}
            </span>
          </div>

          {/* 인자 수준 테이블 */}
          <div>
            <p className="text-xs font-semibold text-gray-400 mb-2">인자 수준 설정</p>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-xs">인자</TableHead>
                  <TableHead className="text-xs">단위</TableHead>
                  <TableHead className="text-xs">Low (−1)</TableHead>
                  <TableHead className="text-xs">Center (0)</TableHead>
                  <TableHead className="text-xs">High (+1)</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {factors.map((f, i) => (
                  <TableRow key={f.name} className={i >= 3 && mode === 'rsm' ? 'opacity-40' : ''}>
                    <TableCell className="text-sm font-medium">{f.name}</TableCell>
                    <TableCell className="text-xs text-gray-500">{f.unit}</TableCell>
                    <TableCell>
                      <Input type="number" className="h-7 w-20 text-xs"
                        value={f.low}
                        onChange={e => setFactors(fs => fs.map((x, j) => j === i ? { ...x, low: +e.target.value } : x))}
                      />
                    </TableCell>
                    <TableCell>
                      <Input type="number" className="h-7 w-20 text-xs"
                        value={f.center}
                        onChange={e => setFactors(fs => fs.map((x, j) => j === i ? { ...x, center: +e.target.value } : x))}
                      />
                    </TableCell>
                    <TableCell>
                      <Input type="number" className="h-7 w-20 text-xs"
                        value={f.high}
                        onChange={e => setFactors(fs => fs.map((x, j) => j === i ? { ...x, high: +e.target.value } : x))}
                      />
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
            {mode === 'rsm' && <p className="text-xs text-gray-400 mt-1">Box-Behnken: 상위 3개 인자만 활성 (나머지는 Center 고정)</p>}
          </div>

          {/* 생성된 실험 세트 */}
          {runs.length > 0 && (
            <div>
              <div className="flex items-center justify-between mb-2">
                <p className="text-xs font-semibold text-gray-400">생성된 실험 세트 ({runs.length}회)</p>
                <Button size="sm" variant="ghost" className="text-xs h-7" onClick={() => {
                  const csv = [
                    ['Run', ...factors.map(f => `${f.name}(${f.unit})`)].join(','),
                    ...runs.map(r => [r.label, ...factors.map(f => r.factors[f.name] ?? '')].join(','))
                  ].join('\n')
                  const blob = new Blob([csv], { type: 'text/csv' })
                  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `DOE_${mode}.csv`; a.click()
                }}>CSV 다운로드</Button>
              </div>
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-xs">Run</TableHead>
                      {factors.map(f => <TableHead key={f.name} className="text-xs">{f.name}</TableHead>)}
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {runs.map(r => (
                      <TableRow key={r.id}>
                        <TableCell className="font-mono text-xs">{r.label}</TableCell>
                        {factors.map(f => (
                          <TableCell key={f.name} className="text-xs font-mono">
                            {r.factors[f.name] != null ? r.factors[f.name].toFixed(1) : '—'}
                          </TableCell>
                        ))}
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

// ──────────────────────────────────────────────
// M4: 실험 트래커
// ──────────────────────────────────────────────
function TrackerTab({ records, onUpdateRecord }: {
  records: ExperimentRecord[]
  onUpdateRecord: (id: number, actual: ExperimentRecord['actual'], note: string) => void
}) {
  const [editId, setEditId] = useState<number | null>(null)
  const [editActual, setEditActual] = useState<ExperimentRecord['actual']>({})
  const [editNote, setEditNote] = useState('')

  const startEdit = (r: ExperimentRecord) => {
    setEditId(r.id)
    setEditActual(r.actual ?? {})
    setEditNote(r.note)
  }

  const saveEdit = (id: number) => {
    onUpdateRecord(id, editActual, editNote)
    setEditId(null)
  }

  if (records.length === 0) {
    return (
      <Card>
        <CardContent className="py-12 text-center text-gray-400 text-sm">
          아직 저장된 배합이 없습니다. [물성 예측] 탭에서 예측 후 트래커 저장 하세요.
        </CardContent>
      </Card>
    )
  }

  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-base">M4 — 실험 트래커 ({records.length}건)</CardTitle>
        <p className="text-xs text-gray-500">실측 결과 입력 후 저장하면 예측-실측 비교가 기록됩니다.</p>
      </CardHeader>
      <CardContent>
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="text-xs">LOT</TableHead>
                <TableHead className="text-xs">날짜</TableHead>
                <TableHead className="text-xs">N-PMI</TableHead>
                <TableHead className="text-xs">g-ABS</TableHead>
                <TableHead className="text-xs">HDT 예측</TableHead>
                <TableHead className="text-xs">HDT 실측</TableHead>
                <TableHead className="text-xs">Izod 예측</TableHead>
                <TableHead className="text-xs">Izod 실측</TableHead>
                <TableHead className="text-xs">VOC 예측</TableHead>
                <TableHead className="text-xs">VOC 실측</TableHead>
                <TableHead className="text-xs">Spec</TableHead>
                <TableHead className="text-xs">메모</TableHead>
                <TableHead className="text-xs"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {records.map(r => (
                <TableRow key={r.id}>
                  <TableCell className="font-mono text-xs font-medium">{r.lot}</TableCell>
                  <TableCell className="text-xs text-gray-500">{r.date}</TableCell>
                  <TableCell className="text-xs">{r.formulation.npmi}%</TableCell>
                  <TableCell className="text-xs">{r.formulation.gAbs}%</TableCell>
                  <TableCell className="text-xs font-mono">{r.prediction.hdt.value.toFixed(1)}℃</TableCell>
                  <TableCell className="text-xs font-mono">
                    {editId === r.id ? (
                      <Input type="number" className="h-6 w-16 text-xs" value={editActual?.hdt ?? ''}
                        onChange={e => setEditActual(a => ({ ...a, hdt: +e.target.value }))} />
                    ) : r.actual?.hdt != null ? (
                      <span className={Math.abs(r.actual.hdt - r.prediction.hdt.value) > 5 ? 'text-orange-600 font-medium' : ''}>
                        {r.actual.hdt.toFixed(1)}℃
                      </span>
                    ) : <span className="text-gray-300">—</span>}
                  </TableCell>
                  <TableCell className="text-xs font-mono">{r.prediction.izod.value.toFixed(1)}</TableCell>
                  <TableCell className="text-xs font-mono">
                    {editId === r.id ? (
                      <Input type="number" className="h-6 w-16 text-xs" value={editActual?.izod ?? ''}
                        onChange={e => setEditActual(a => ({ ...a, izod: +e.target.value }))} />
                    ) : r.actual?.izod != null ? r.actual.izod.toFixed(1) : <span className="text-gray-300">—</span>}
                  </TableCell>
                  <TableCell className="text-xs font-mono">{r.prediction.voc.value.toFixed(0)}</TableCell>
                  <TableCell className="text-xs font-mono">
                    {editId === r.id ? (
                      <Input type="number" className="h-6 w-16 text-xs" value={editActual?.voc ?? ''}
                        onChange={e => setEditActual(a => ({ ...a, voc: +e.target.value }))} />
                    ) : r.actual?.voc != null ? r.actual.voc.toFixed(0) : <span className="text-gray-300">—</span>}
                  </TableCell>
                  <TableCell>
                    <div className="flex gap-1">
                      <SpecLight pass={r.prediction.specPass.hdt} />
                      <SpecLight pass={r.prediction.specPass.izod} />
                      <SpecLight pass={r.prediction.specPass.voc} />
                    </div>
                  </TableCell>
                  <TableCell className="text-xs max-w-[120px]">
                    {editId === r.id ? (
                      <Input className="h-6 text-xs" value={editNote}
                        onChange={e => setEditNote(e.target.value)} />
                    ) : <span className="text-gray-500 truncate block">{r.note || '—'}</span>}
                  </TableCell>
                  <TableCell>
                    {editId === r.id ? (
                      <Button size="sm" className="h-6 text-xs px-2" onClick={() => saveEdit(r.id)}>저장</Button>
                    ) : (
                      <Button size="sm" variant="ghost" className="h-6 text-xs px-2" onClick={() => startEdit(r)}>입력</Button>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>

        {records.some(r => r.actual?.hdt != null) && (
          <div className="mt-4 p-3 bg-gray-50 rounded text-xs text-gray-600">
            <p className="font-semibold mb-1">예측-실측 비교 요약</p>
            {(() => {
              const pairs = records.filter(r => r.actual?.hdt != null)
              const hdtErr = pairs.reduce((s, r) => s + Math.abs(r.actual!.hdt! - r.prediction.hdt.value), 0) / pairs.length
              return <p>HDT 평균 절대오차: <strong>{hdtErr.toFixed(1)}℃</strong> (N={pairs.length})</p>
            })()}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

// ──────────────────────────────────────────────
// 메인 App
// ──────────────────────────────────────────────
export default function App() {
  const [records, setRecords] = useState<ExperimentRecord[]>([])

  const handleAddRecord = useCallback((r: ExperimentRecord) => {
    setRecords(prev => [r, ...prev])
  }, [])

  const handleUpdateRecord = useCallback((id: number, actual: ExperimentRecord['actual'], note: string) => {
    setRecords(prev => prev.map(r => r.id === id ? { ...r, actual, note } : r))
  }, [])

  return (
    <div className="min-h-screen bg-gray-50 font-sans">
      {/* 헤더 */}
      <div className="bg-white border-b px-6 py-3">
        <div className="max-w-7xl mx-auto flex items-baseline gap-3">
          <h1 className="text-lg font-bold tracking-tight">내열 ABS 컴파운드 가상 실험 시뮬레이터</h1>
          <span className="text-xs text-gray-400">N-PMI 내열 ABS · 자동차 내장재 · HDT 115℃+ Track</span>
          <span className="ml-auto">
            <Badge variant="secondary" className="text-xs">v1 MVP — P0 모듈</Badge>
          </span>
        </div>
        <div className="max-w-7xl mx-auto mt-0.5 flex gap-4 text-xs text-gray-500">
          <span>목표: HDT ≥ 115℃ · Izod ≥ 15 kJ/m² · TVOC ≤ 50 µg/g</span>
          <span className="ml-auto">실험 트래커: {records.length}건</span>
        </div>
      </div>

      {/* 메인 콘텐츠 */}
      <div className="max-w-7xl mx-auto p-4">
        <Tabs defaultValue="predict">
          <TabsList className="mb-4">
            <TabsTrigger value="predict">물성 예측 (M1·M2)</TabsTrigger>
            <TabsTrigger value="doe">DOE 설계 (M3)</TabsTrigger>
            <TabsTrigger value="tracker">
              실험 트래커 (M4)
              {records.length > 0 && <Badge variant="secondary" className="ml-1.5 text-xs px-1.5 py-0">{records.length}</Badge>}
            </TabsTrigger>
          </TabsList>

          <TabsContent value="predict">
            <PredictorTab records={records} onAddRecord={handleAddRecord} />
          </TabsContent>

          <TabsContent value="doe">
            <DOETab />
          </TabsContent>

          <TabsContent value="tracker">
            <TrackerTab records={records} onUpdateRecord={handleUpdateRecord} />
          </TabsContent>
        </Tabs>
      </div>

      {/* 푸터 */}
      <div className="border-t bg-white mt-8 px-6 py-3 text-xs text-gray-400 max-w-7xl mx-auto">
        Cold-start 예측: Fox 식(Matrix Tg) + HDT-Tg 상관 + 고무-충격 경험 곡선.
        데이터 0건 기준 오차 ±7~30%. 실측 데이터 누적 시 대리모델(GPR/RSM) 자동 보정 예정 (v2).
        VDA 278 TVOC &lt; 50µg/g · VDA 270 Odor · MS 300-55 기준.
      </div>
    </div>
  )
}

toolUseResult.content:
import { useState, useCallback } from 'react'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Slider } from '@/components/ui/slider'
import { Badge } from '@/components/ui/badge'
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import {
  predictColdStart,
  generateScreeningDOE,
  generateRSMDOE,
  DEFAULT_FACTORS,
  type Formulation,
  type PredictionResult,
  type DOERun,
} from '@/lib/physics'

// ──────────────────────────────────────────────
// 타입 정의
// ──────────────────────────────────────────────
interface ExperimentRecord {
  id: number
  lot: string
  formulation: Formulation
  prediction: PredictionResult
  actual?: {
    hdt?: number
    izod?: number
    mfi?: number
    voc?: number
  }
  date: string
  note: string
}

// ──────────────────────────────────────────────
// 상수
// ──────────────────────────────────────────────
const SPEC = {
  hdt: { target: 115, unit: '℃', label: 'HDT (1.8MPa)' },
  izod: { target: 15, unit: 'kJ/m²', label: 'Izod 충격' },
  voc: { target: 50, unit: 'µg/g', label: 'TVOC (VDA278)' },
}

const DEFAULT_FORM: Formulation = {
  npmi: 17,
  gAbs: 28,
  san: 50,
  anContent: 28,
  cbMB: 2.5,
  antioxidant: 0.5,
  lubricant: 1.0,
  injTemp: 250,
  moldTemp: 70,
}

// ──────────────────────────────────────────────
// 유틸 컴포넌트
// ──────────────────────────────────────────────
function SpecLight({ pass }: { pass: boolean | null }) {
  if (pass === true) return <span className="inline-block w-3 h-3 rounded-full bg-green-500" title="통과" />
  if (pass === false) return <span className="inline-block w-3 h-3 rounded-full bg-red-500" title="미달" />
  return <span className="inline-block w-3 h-3 rounded-full bg-yellow-400" title="주의" />
}

function PredBar({ value, low, high, unit, spec, higherIsBad = false }: {
  value: number; low: number; high: number; unit: string; spec?: number; higherIsBad?: boolean
}) {
  const pass = spec == null ? null : higherIsBad ? value <= spec : value >= spec
  const color = pass === true ? 'text-green-600' : pass === false ? 'text-red-600' : 'text-yellow-600'
  return (
    <div className="flex items-center gap-3">
      <span className={`font-mono text-lg font-bold w-24 text-right ${color}`}>
        {value.toFixed(1)}<span className="text-xs font-normal ml-1">{unit}</span>
      </span>
      <span className="text-xs text-gray-400 font-mono">
        [{low.toFixed(1)} – {high.toFixed(1)}]
      </span>
      {spec != null && <SpecLight pass={pass} />}
    </div>
  )
}

function SliderRow({ label, value, min, max, step = 0.5, unit, onChange, warn }: {
  label: string; value: number; min: number; max: number; step?: number; unit: string;
  onChange: (v: number) => void; warn?: string
}) {
  return (
    <div className="grid grid-cols-[160px_1fr_64px] items-center gap-3 py-1">
      <Label className="text-sm">{label}</Label>
      <Slider
        min={min} max={max} step={step} value={[value]}
        onValueChange={([v]) => onChange(v)}
        className="w-full"
      />
      <span className="text-sm font-mono text-right">
        {value}<span className="text-gray-400 text-xs ml-0.5">{unit}</span>
      </span>
      {warn && <span className="col-span-3 text-xs text-yellow-600 -mt-1">{warn}</span>}
    </div>
  )
}

// ──────────────────────────────────────────────
// M1 + M2: 배합 입력기 & 물성 예측기
// ──────────────────────────────────────────────
function PredictorTab({ records, onAddRecord }: {
  records: ExperimentRecord[]
  onAddRecord: (r: ExperimentRecord) => void
}) {
  const [form, setForm] = useState<Formulation>(DEFAULT_FORM)
  const [pred, setPred] = useState<PredictionResult | null>(null)
  const [lotName, setLotName] = useState('')

  const totalComposition = form.npmi + form.gAbs + form.cbMB
  const sanEst = Math.max(0, 100 - totalComposition)
  const compositonOk = totalComposition <= 100

  const set = useCallback((key: keyof Formulation) => (v: number) => {
    setForm(f => ({ ...f, [key]: v }))
    setPred(null)
  }, [])

  const handlePredict = () => {
    const result = predictColdStart({ ...form, san: sanEst })
    setPred(result)
  }

  const handleSave = () => {
    if (!pred) return
    const rec: ExperimentRecord = {
      id: Date.now(),
      lot: lotName || `LOT-${records.length + 1}`,
      formulation: { ...form, san: sanEst },
      prediction: pred,
      date: new Date().toLocaleDateString('ko-KR'),
      note: '',
    }
    onAddRecord(rec)
    setLotName('')
  }

  return (
    <div className="grid grid-cols-[1fr_340px] gap-4">
      {/* 왼쪽: 입력 패널 */}
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-base">M1 — 배합 입력기</CardTitle>
          <p className="text-xs text-gray-500">조성 합계: <strong className={compositonOk ? 'text-green-600' : 'text-red-600'}>{totalComposition.toFixed(1)} wt%</strong> (CB·AO·활제 별도) / SAN 추정: <strong>{sanEst.toFixed(1)} wt%</strong></p>
        </CardHeader>
        <CardContent className="space-y-1">
          <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide pt-1">── 주요 조성</p>
          <SliderRow label="N-PMI 함량" value={form.npmi} min={10} max={25} step={0.5} unit="wt%" onChange={set('npmi')} />
          <SliderRow label="g-ABS(고무)" value={form.gAbs} min={20} max={40} step={0.5} unit="wt%" onChange={set('gAbs')} />
          <SliderRow label="SAN AN 함량" value={form.anContent} min={24} max={32} step={0.5} unit="%" onChange={set('anContent')} />
          <SliderRow label="카본블랙 MB" value={form.cbMB} min={2} max={3} step={0.1} unit="wt%" onChange={set('cbMB')} />

          <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide pt-3">── 첨가제</p>
          <SliderRow label="산화방지제" value={form.antioxidant} min={0.3} max={0.8} step={0.05} unit="phr" onChange={set('antioxidant')} />
          <SliderRow label="활제 (EBS)" value={form.lubricant} min={0.5} max={1.5} step={0.1} unit="phr" onChange={set('lubricant')} />

          <p className="text-xs font-semibold text-gray-400 uppercase tracking-wide pt-3">── 공정 조건</p>
          <SliderRow label="사출 온도" value={form.injTemp} min={240} max={260} step={1} unit="℃" onChange={set('injTemp')}
            warn={form.injTemp > 255 ? '⚠ 고온 체류 시 VOC 증가 위험' : undefined} />
          <SliderRow label="금형 온도" value={form.moldTemp} min={60} max={80} step={1} unit="℃" onChange={set('moldTemp')} />

          {!compositonOk && (
            <p className="text-xs text-red-600 pt-1">⚠ 조성 합계가 100%를 초과합니다. N-PMI 또는 g-ABS를 줄이세요.</p>
          )}

          <div className="flex gap-2 pt-3">
            <Button onClick={handlePredict} disabled={!compositonOk} className="flex-1">
              물성 예측 실행
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* 오른쪽: 예측 결과 */}
      <div className="space-y-3">
        <Card>
          <CardHeader className="pb-2">
            <div className="flex items-center justify-between">
              <CardTitle className="text-base">M2 — 물성 예측 결과</CardTitle>
              {pred && (
                <Badge variant="outline" className="text-xs">
                  Cold-start (데이터 0건)
                </Badge>
              )}
            </div>
          </CardHeader>
          <CardContent>
            {!pred ? (
              <p className="text-sm text-gray-400 text-center py-6">배합 입력 후 [물성 예측 실행] 클릭</p>
            ) : (
              <div className="space-y-3">
                <div className="grid grid-cols-[120px_1fr] gap-y-2 text-sm">
                  <span className="text-gray-500">{SPEC.hdt.label}</span>
                  <PredBar {...pred.hdt} unit="℃" spec={SPEC.hdt.target} />
                  <span className="text-gray-500">Vicat</span>
                  <PredBar {...pred.vicat} unit="℃" />
                  <span className="text-gray-500">{SPEC.izod.label}</span>
                  <PredBar {...pred.izod} unit="kJ/m²" spec={SPEC.izod.target} />
                  <span className="text-gray-500">MFI (220℃/10kg)</span>
                  <PredBar {...pred.mfi} unit="g/10min" />
                  <span className="text-gray-500">{SPEC.voc.label}</span>
                  <PredBar {...pred.voc} unit="µg/g" spec={SPEC.voc.target} higherIsBad />
                  <span className="text-gray-500">원가 지수</span>
                  <PredBar {...pred.cost} unit="₩/kg" />
                </div>

                {/* Spec 게이트 신호등 */}
                <div className="border-t pt-2 mt-2">
                  <p className="text-xs font-semibold text-gray-400 mb-2">M8 — Spec 게이트 판정</p>
                  <div className="flex gap-3">
                    {Object.entries(pred.specPass).map(([key, val]) => (
                      <div key={key} className="flex items-center gap-1.5 text-xs">
                        <SpecLight pass={val} />
                        <span>{key.toUpperCase()} {SPEC[key as keyof typeof SPEC]?.target}{SPEC[key as keyof typeof SPEC]?.unit}</span>
                      </div>
                    ))}
                  </div>
                  <p className="text-xs text-gray-400 mt-2">
                    오차범위는 cold-start 기준 (±7~30%). 실측 데이터 누적 시 신뢰구간 축소.
                  </p>
                </div>

                {/* 저장 */}
                <div className="border-t pt-2 flex gap-2">
                  <Input
                    placeholder="LOT 번호 (선택)"
                    value={lotName}
                    onChange={e => setLotName(e.target.value)}
                    className="text-sm h-8"
                  />
                  <Button size="sm" variant="outline" onClick={handleSave}>
                    트래커 저장
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Trade-off 요약 */}
        {pred && (
          <Card>
            <CardHeader className="pb-1">
              <CardTitle className="text-sm">Trade-off 인사이트</CardTitle>
            </CardHeader>
            <CardContent className="text-xs space-y-1 text-gray-600">
              {form.npmi > 20 && <p>🔺 N-PMI {form.npmi}% — 내열↑ 좋지만 충격↓·MFI↓ 주의</p>}
              {form.npmi < 13 && <p>🔻 N-PMI {form.npmi}% — 충격·유동↑ 좋지만 HDT 115℃ 달성 어려울 수 있음</p>}
              {form.gAbs > 35 && <p>🔺 고무 {form.gAbs}% — 충격↑이지만 HDT·강성↓, VOC도 증가 경향</p>}
              {form.injTemp > 255 && <p>⚠ 사출온도 {form.injTemp}℃ — 체류 길어지면 TVOC spike 위험 (VDA278 미달 리스크)</p>}
              {pred.specPass.hdt === false && <p>❌ HDT 미달 예측 → N-PMI 2~3% 추가 검토 또는 DOE 실험 설계 권장</p>}
              {pred.specPass.voc === false && <p>❌ VOC 초과 예측 → 탈휘발 조건 강화 또는 산화방지제 패키지 재검토</p>}
              {pred.specPass.hdt === true && pred.specPass.izod === true && pred.specPass.voc === true && (
                <p>✅ 현 배합이 3대 Spec 통과 예측. 실배합으로 검증 권장.</p>
              )}
              {pred.specPass.hdt === null && <p>⚠ HDT 경계구간 (110~115℃) — 실험 우선 실시 권장</p>}
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  )
}

// ──────────────────────────────────────────────
// M3: DOE 설계기
// ──────────────────────────────────────────────
function DOETab() {
  const [mode, setMode] = useState<'screening' | 'rsm'>('screening')
  const [factors, setFactors] = useState(DEFAULT_FACTORS)
  const [runs, setRuns] = useState<DOERun[]>([])

  const handleGenerate = () => {
    const result = mode === 'screening'
      ? generateScreeningDOE(factors)
      : generateRSMDOE(factors)
    setRuns(result)
  }

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-base">M3 — DOE 설계기</CardTitle>
          <p className="text-xs text-gray-500">
            스크리닝: PB12 (12회, 7인자 주효과 분리) → RSM: Box-Behnken (15회, 지배 3인자 곡률·상호작용)
          </p>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex gap-3 items-center">
            <Select value={mode} onValueChange={v => { setMode(v as typeof mode); setRuns([]) }}>
              <SelectTrigger className="w-56">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="screening">스크리닝 DOE — Plackett-Burman 12</SelectItem>
                <SelectItem value="rsm">반응표면 DOE — Box-Behnken 15</SelectItem>
              </SelectContent>
            </Select>
            <Button onClick={handleGenerate}>실험 세트 생성</Button>
            <span className="text-xs text-gray-400">
              {mode === 'screening' ? '예상 실험 수: 12회' : '예상 실험 수: 15회'}
            </span>
          </div>

          {/* 인자 수준 테이블 */}
          <div>
            <p className="text-xs font-semibold text-gray-400 mb-2">인자 수준 설정</p>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-xs">인자</TableHead>
                  <TableHead className="text-xs">단위</TableHead>
                  <TableHead className="text-xs">Low (−1)</TableHead>
                  <TableHead className="text-xs">Center (0)</TableHead>
                  <TableHead className="text-xs">High (+1)</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {factors.map((f, i) => (
                  <TableRow key={f.name} className={i >= 3 && mode === 'rsm' ? 'opacity-40' : ''}>
                    <TableCell className="text-sm font-medium">{f.name}</TableCell>
                    <TableCell className="text-xs text-gray-500">{f.unit}</TableCell>
                    <TableCell>
                      <Input type="number" className="h-7 w-20 text-xs"
                        value={f.low}
                        onChange={e => setFactors(fs => fs.map((x, j) => j === i ? { ...x, low: +e.target.value } : x))}
                      />
                    </TableCell>
                    <TableCell>
                      <Input type="number" className="h-7 w-20 text-xs"
                        value={f.center}
                        onChange={e => setFactors(fs => fs.map((x, j) => j === i ? { ...x, center: +e.target.value } : x))}
                      />
                    </TableCell>
                    <TableCell>
                      <Input type="number" className="h-7 w-20 text-xs"
                        value={f.high}
                        onChange={e => setFactors(fs => fs.map((x, j) => j === i ? { ...x, high: +e.target.value } : x))}
                      />
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
            {mode === 'rsm' && <p className="text-xs text-gray-400 mt-1">Box-Behnken: 상위 3개 인자만 활성 (나머지는 Center 고정)</p>}
          </div>

          {/* 생성된 실험 세트 */}
          {runs.length > 0 && (
            <div>
              <div className="flex items-center justify-between mb-2">
                <p className="text-xs font-semibold text-gray-400">생성된 실험 세트 ({runs.length}회)</p>
                <Button size="sm" variant="ghost" className="text-xs h-7" onClick={() => {
                  const csv = [
                    ['Run', ...factors.map(f => `${f.name}(${f.unit})`)].join(','),
                    ...runs.map(r => [r.label, ...factors.map(f => r.factors[f.name] ?? '')].join(','))
                  ].join('\n')
                  const blob = new Blob([csv], { type: 'text/csv' })
                  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `DOE_${mode}.csv`; a.click()
                }}>CSV 다운로드</Button>
              </div>
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-xs">Run</TableHead>
                      {factors.map(f => <TableHead key={f.name} className="text-xs">{f.name}</TableHead>)}
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {runs.map(r => (
                      <TableRow key={r.id}>
                        <TableCell className="font-mono text-xs">{r.label}</TableCell>
                        {factors.map(f => (
                          <TableCell key={f.name} className="text-xs font-mono">
                            {r.factors[f.name] != null ? r.factors[f.name].toFixed(1) : '—'}
                          </TableCell>
                        ))}
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

// ──────────────────────────────────────────────
// M4: 실험 트래커
// ──────────────────────────────────────────────
function TrackerTab({ records, onUpdateRecord }: {
  records: ExperimentRecord[]
  onUpdateRecord: (id: number, actual: ExperimentRecord['actual'], note: string) => void
}) {
  const [editId, setEditId] = useState<number | null>(null)
  const [editActual, setEditActual] = useState<ExperimentRecord['actual']>({})
  const [editNote, setEditNote] = useState('')

  const startEdit = (r: ExperimentRecord) => {
    setEditId(r.id)
    setEditActual(r.actual ?? {})
    setEditNote(r.note)
  }

  const saveEdit = (id: number) => {
    onUpdateRecord(id, editActual, editNote)
    setEditId(null)
  }

  if (records.length === 0) {
    return (
      <Card>
        <CardContent className="py-12 text-center text-gray-400 text-sm">
          아직 저장된 배합이 없습니다. [물성 예측] 탭에서 예측 후 트래커 저장 하세요.
        </CardContent>
      </Card>
    )
  }

  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-base">M4 — 실험 트래커 ({records.length}건)</CardTitle>
        <p className="text-xs text-gray-500">실측 결과 입력 후 저장하면 예측-실측 비교가 기록됩니다.</p>
      </CardHeader>
      <CardContent>
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="text-xs">LOT</TableHead>
                <TableHead className="text-xs">날짜</TableHead>
                <TableHead className="text-xs">N-PMI</TableHead>
                <TableHead className="text-xs">g-ABS</TableHead>
                <TableHead className="text-xs">HDT 예측</TableHead>
                <TableHead className="text-xs">HDT 실측</TableHead>
                <TableHead className="text-xs">Izod 예측</TableHead>
                <TableHead className="text-xs">Izod 실측</TableHead>
                <TableHead className="text-xs">VOC 예측</TableHead>
                <TableHead className="text-xs">VOC 실측</TableHead>
                <TableHead className="text-xs">Spec</TableHead>
                <TableHead className="text-xs">메모</TableHead>
                <TableHead className="text-xs"></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {records.map(r => (
                <TableRow key={r.id}>
                  <TableCell className="font-mono text-xs font-medium">{r.lot}</TableCell>
                  <TableCell className="text-xs text-gray-500">{r.date}</TableCell>
                  <TableCell className="text-xs">{r.formulation.npmi}%</TableCell>
                  <TableCell className="text-xs">{r.formulation.gAbs}%</TableCell>
                  <TableCell className="text-xs font-mono">{r.prediction.hdt.value.toFixed(1)}℃</TableCell>
                  <TableCell className="text-xs font-mono">
                    {editId === r.id ? (
                      <Input type="number" className="h-6 w-16 text-xs" value={editActual?.hdt ?? ''}
                        onChange={e => setEditActual(a => ({ ...a, hdt: +e.target.value }))} />
                    ) : r.actual?.hdt != null ? (
                      <span className={Math.abs(r.actual.hdt - r.prediction.hdt.value) > 5 ? 'text-orange-600 font-medium' : ''}>
                        {r.actual.hdt.toFixed(1)}℃
                      </span>
                    ) : <span className="text-gray-300">—</span>}
                  </TableCell>
                  <TableCell className="text-xs font-mono">{r.prediction.izod.value.toFixed(1)}</TableCell>
                  <TableCell className="text-xs font-mono">
                    {editId === r.id ? (
                      <Input type="number" className="h-6 w-16 text-xs" value={editActual?.izod ?? ''}
                        onChange={e => setEditActual(a => ({ ...a, izod: +e.target.value }))} />
                    ) : r.actual?.izod != null ? r.actual.izod.toFixed(1) : <span className="text-gray-300">—</span>}
                  </TableCell>
                  <TableCell className="text-xs font-mono">{r.prediction.voc.value.toFixed(0)}</TableCell>
                  <TableCell className="text-xs font-mono">
                    {editId === r.id ? (
                      <Input type="number" className="h-6 w-16 text-xs" value={editActual?.voc ?? ''}
                        onChange={e => setEditActual(a => ({ ...a, voc: +e.target.value }))} />
                    ) : r.actual?.voc != null ? r.actual.voc.toFixed(0) : <span className="text-gray-300">—</span>}
                  </TableCell>
                  <TableCell>
                    <div className="flex gap-1">
                      <SpecLight pass={r.prediction.specPass.hdt} />
                      <SpecLight pass={r.prediction.specPass.izod} />
                      <SpecLight pass={r.prediction.specPass.voc} />
                    </div>
                  </TableCell>
                  <TableCell className="text-xs max-w-[120px]">
                    {editId === r.id ? (
                      <Input className="h-6 text-xs" value={editNote}
                        onChange={e => setEditNote(e.target.value)} />
                    ) : <span className="text-gray-500 truncate block">{r.note || '—'}</span>}
                  </TableCell>
                  <TableCell>
                    {editId === r.id ? (
                      <Button size="sm" className="h-6 text-xs px-2" onClick={() => saveEdit(r.id)}>저장</Button>
                    ) : (
                      <Button size="sm" variant="ghost" className="h-6 text-xs px-2" onClick={() => startEdit(r)}>입력</Button>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>

        {records.some(r => r.actual?.hdt != null) && (
          <div className="mt-4 p-3 bg-gray-50 rounded text-xs text-gray-600">
            <p className="font-semibold mb-1">예측-실측 비교 요약</p>
            {(() => {
              const pairs = records.filter(r => r.actual?.hdt != null)
              const hdtErr = pairs.reduce((s, r) => s + Math.abs(r.actual!.hdt! - r.prediction.hdt.value), 0) / pairs.length
              return <p>HDT 평균 절대오차: <strong>{hdtErr.toFixed(1)}℃</strong> (N={pairs.length})</p>
            })()}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

// ──────────────────────────────────────────────
// 메인 App
// ──────────────────────────────────────────────
export default function App() {
  const [records, setRecords] = useState<ExperimentRecord[]>([])

  const handleAddRecord = useCallback((r: ExperimentRecord) => {
    setRecords(prev => [r, ...prev])
  }, [])

  const handleUpdateRecord = useCallback((id: number, actual: ExperimentRecord['actual'], note: string) => {
    setRecords(prev => prev.map(r => r.id === id ? { ...r, actual, note } : r))
  }, [])

  return (
    <div className="min-h-screen bg-gray-50 font-sans">
      {/* 헤더 */}
      <div className="bg-white border-b px-6 py-3">
        <div className="max-w-7xl mx-auto flex items-baseline gap-3">
          <h1 className="text-lg font-bold tracking-tight">내열 ABS 컴파운드 가상 실험 시뮬레이터</h1>
          <span className="text-xs text-gray-400">N-PMI 내열 ABS · 자동차 내장재 · HDT 115℃+ Track</span>
          <span className="ml-auto">
            <Badge variant="secondary" className="text-xs">v1 MVP — P0 모듈</Badge>
          </span>
        </div>
        <div className="max-w-7xl mx-auto mt-0.5 flex gap-4 text-xs text-gray-500">
          <span>목표: HDT ≥ 115℃ · Izod ≥ 15 kJ/m² · TVOC ≤ 50 µg/g</span>
          <span className="ml-auto">실험 트래커: {records.length}건</span>
        </div>
      </div>

      {/* 메인 콘텐츠 */}
      <div className="max-w-7xl mx-auto p-4">
        <Tabs defaultValue="predict">
          <TabsList className="mb-4">
            <TabsTrigger value="predict">물성 예측 (M1·M2)</TabsTrigger>
            <TabsTrigger value="doe">DOE 설계 (M3)</TabsTrigger>
            <TabsTrigger value="tracker">
              실험 트래커 (M4)
              {records.length > 0 && <Badge variant="secondary" className="ml-1.5 text-xs px-1.5 py-0">{records.length}</Badge>}
            </TabsTrigger>
          </TabsList>

          <TabsContent value="predict">
            <PredictorTab records={records} onAddRecord={handleAddRecord} />
          </TabsContent>

          <TabsContent value="doe">
            <DOETab />
          </TabsContent>

          <TabsContent value="tracker">
            <TrackerTab records={records} onUpdateRecord={handleUpdateRecord} />
          </TabsContent>
        </Tabs>
      </div>

      {/* 푸터 */}
      <div className="border-t bg-white mt-8 px-6 py-3 text-xs text-gray-400 max-w-7xl mx-auto">
        Cold-start 예측: Fox 식(Matrix Tg) + HDT-Tg 상관 + 고무-충격 경험 곡선.
        데이터 0건 기준 오차 ±7~30%. 실측 데이터 누적 시 대리모델(GPR/RSM) 자동 보정 예정 (v2).
        VDA 278 TVOC &lt; 50µg/g · VDA 270 Odor · MS 300-55 기준.
      </div>
    </div>
  )
}
